import{_ as a,c as t,o as e,a4 as l}from"./chunks/framework.dBUWB6Kx.js";const T=JSON.parse('{"title":"TCP","description":"","frontmatter":{},"headers":[],"relativePath":"modules/web/javascript/TCP.md","filePath":"modules/web/javascript/TCP.md","lastUpdated":1773861737000}'),i={name:"modules/web/javascript/TCP.md"},o=l('<h1 id="tcp" tabindex="-1">TCP <a class="header-anchor" href="#tcp" aria-label="Permalink to &quot;TCP&quot;">​</a></h1><p>TCP(Transmission Control Protocol 传输控制协议)是一种面向连接(连接导向)的、可靠的、 基于IP的传输层协议。TCP在IP报文的协议号是6。</p><h2 id="tcp三次握手的含义和意义" tabindex="-1">TCP三次握手的含义和意义 <a class="header-anchor" href="#tcp三次握手的含义和意义" aria-label="Permalink to &quot;TCP三次握手的含义和意义&quot;">​</a></h2><ul><li>1.第一次握手：客户端发送请求建立连接，请求报文段。</li><li>2.第二次握手：服务器收到请求，发送同意并请求与客户端建立连接。</li><li>3.第三次握手：客户端收到请求，发送同意与服务器建立连接。</li></ul><p>为了防止已失效的连接请求报文段突然又传送到了服务端，因而产生错误。 第一次和第二次握手为了保证服务端能够接受到客户端的信息并能做出正确的应答， 第二次和第三次握手为了保证客户端能够接收到服务端的信息并能做出正确的应答而进行后两次。</p><h2 id="tcp四次分手的含义和意义" tabindex="-1">TCP四次分手的含义和意义 <a class="header-anchor" href="#tcp四次分手的含义和意义" aria-label="Permalink to &quot;TCP四次分手的含义和意义&quot;">​</a></h2><p>数据传送完毕，相应的就要断开TCP连接</p><ul><li><p>1.第一次分手：客户端发送断开请求</p></li><li><p>2.第二次分手：服务器收到断开请求，发送同意断开连接的请求</p></li><li><p>3.第三次分手：服务器发送请求断开连接</p></li><li><p>4.第四次分手：客户端收到，发送同意断开连接</p></li><li><p>1.当客户端发送断开请求，只是表示客户端已经没有数据要发送了，客户端告诉服务器，它的数据已经全部发送完毕了，但是，这个时候客户端还是可以接受来自服务器的数据(第一次分手)</p></li><li><p>2.当服务器收到断开请求时，表示它已经知道客户端没有数据发送了并发送同意断开连接的请求，但是服务器还是可以发送数据到客户端的（第二次分手）</p></li><li><p>3.当服务器发送同意断开连接的请求后，这个时候就表示服务器也没有数据要发送了，就会告诉客户端，我也没有数据要发送了（第三次分手）</p></li><li><p>4.当客户端收到服务器发送请求断开连接后，再去告诉服务端我已经知道你没有数据要发给我了，同意断开连接请求（第四次分手）</p></li></ul>',8),p=[o];function r(s,c,n,d,_,P){return e(),t("div",null,p)}const u=a(i,[["render",r]]);export{T as __pageData,u as default};
